def bfs2(start,cap=60000,maxd=20,goal=lambda s: s[4][2]<=12):
    import collections
    seen={start:None}; q=collections.deque([(start,0)]); n=0
    while q:
        st,d=q.popleft()
        if d>=maxd: continue
        for gi in range(5):
            for gr in (True,False):
                s3=actL(st,gi,gr); n+=1
                if s3 is None or s3 in seen: continue
                seen[s3]=(st,gi,gr)
                if goal(s3):
                    path=[]; cur=s3
                    while seen[cur] is not None:
                        p,c2,g2=seen[cur]; path.append((c2,g2)); cur=p
                    return list(reversed(path)),len(seen)
                if len(seen)>cap: return None,len(seen)
                q.append((s3,d+1))
    return None,len(seen)
