def tok_bfs(g, start):
    from collections import deque
    R=len(g); C=38
    def ok(r,c):
        if not(0<=r and r+1<R and 0<=c and c+1<C): return False
        for rr in (r,r+1):
            for cc in (c,c+1):
                if g[rr][cc]=='c': return False
        return True
    seen={start}; par={start:None}; dq=deque([start])
    while dq:
        n=dq.popleft()
        for dr,dc,act in ((-2,0,'UP'),(2,0,'DOWN'),(0,-2,'LEFT'),(0,2,'RIGHT')):
            m=(n[0]+dr,n[1]+dc)
            if m not in seen and ok(*m): seen.add(m); par[m]=n; dq.append(m)
    return seen,par
