def bigcomp(a,ch):
    seen=set();best=[]
    for r in range(64):
        for c in range(64):
            if a[r][c]==ch and (r,c) not in seen: continue
            if a[r][c]!=ch: continue
            st=[(r,c)];seen.add((r,c));comp=[]
            while st:
                x,y=st.pop();comp.append((x,y))
                for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<64 and 0<=ny<64 and a[nx][ny]==ch and (nx,ny) not in seen:
                        seen.add((nx,ny));st.append((nx,ny))
            if len(comp)>len(best): best=comp
    return best
